from __future__ import annotations

from app.platform.ui.founder_dashboard_stable import render_stable_founder_dashboard


def render_board_chat_dashboard() -> str:
    html = render_stable_founder_dashboard()
    html = html.replace("<button class='primary' onclick='openBoardRoom()'>Start Discussion</button>", "<button class='primary' onclick='newBoardChat()'>New Chat</button>")
    html = html.replace("<h2>Board Room Discussion</h2><button class='secondary' onclick='closeBoardRoom()'>Close</button>", "<h2>Board Room Executive Chat</h2><div><button class='secondary' onclick='newBoardChat()'>New Chat</button> <button class='secondary' onclick='closeBoardRoom()'>Close</button></div>")
    html = html.replace("<textarea id='message' placeholder='Tell the Board Room what you want to discuss.'></textarea>", "<div class='board-chat-note'>Chat-style Board Room workspace. Use New Chat to reset the session. The right panel captures decisions, actions, and knowledge notes.</div><textarea id='message' placeholder='Message the Board Room...' rows='3'></textarea>")
    html = html.replace("Start Board Room Discussion", "Send")
    html = html.replace("<h3>Board Room Response</h3><pre id='result'>Type a message and start the discussion.</pre>", "<div class='board-chat-grid'><section><h3>Chat</h3><pre id='result'>Start a new Board Room chat.</pre></section><aside class='board-minutes'><h3>Minutes</h3><p><strong>Decisions</strong></p><ul id='decisionMinutes'><li>No decisions captured yet.</li></ul><p><strong>Actions</strong></p><ul id='actionMinutes'><li>No actions captured yet.</li></ul><p><strong>Knowledge</strong></p><ul id='knowledgeMinutes'><li>Important context will appear here.</li></ul><p id='meetingMeta' class='muted'>No meeting yet.</p></aside></div>")
    html = html.replace("</style>", ".board-chat-note{border:1px solid var(--line);background:#07101e;border-radius:12px;padding:12px;margin-bottom:12px;color:var(--muted)}.board-chat-grid{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:14px}.board-minutes{border:1px solid var(--line);border-radius:12px;padding:14px;background:#07101e}.board-minutes ul{padding-left:18px;color:#dbeafe}.board-minutes li{margin:6px 0}@media(max-width:900px){.board-chat-grid{grid-template-columns:1fr}}\n</style>")
    html = html.replace("window.openBoardRoom=function(){byId('boardModal').classList.add('active')};window.closeBoardRoom=function(){byId('boardModal').classList.remove('active')};window.startCommand=function(){byId('message').value=byId('commandInput').value||'';openBoardRoom()};", "function fillMinutes(text,meeting){var sentences=String(text||'').split(/[\\n.]+/).map(function(x){return x.trim()}).filter(Boolean);function set(id,words,empty){var el=byId(id);if(!el)return;el.innerHTML='';var items=sentences.filter(function(s){return words.test(s)}).slice(0,5);if(!items.length)items=[empty];items.forEach(function(s){var li=document.createElement('li');li.textContent=s;el.appendChild(li)})}set('decisionMinutes',/recommend|decision|approve|should|priority/i,'No decisions captured yet.');set('actionMinutes',/next|action|implement|build|fix|audit|review|merge|deploy/i,'No actions captured yet.');set('knowledgeMinutes',/risk|guardrail|architecture|company|github|gcp|context|because/i,'Important context will appear here.');var meta=byId('meetingMeta');if(meta)meta.textContent=meeting||'No meeting yet.'}window.newBoardChat=function(){if(byId('message'))byId('message').value='';show('New Board Room chat started.');fillMinutes('','No meeting yet.');openBoardRoom()};window.openBoardRoom=function(){byId('boardModal').classList.add('active')};window.closeBoardRoom=function(){byId('boardModal').classList.remove('active')};window.startCommand=function(){byId('message').value=byId('commandInput').value||'';openBoardRoom()};")
    html = html.replace("if(data.board_room_response){show(data.board_room_response+'\\n\\n---\\nMeeting ID: '+data.meeting_id+'\\nStatus: '+data.status)}else{show(data)}", "if(data.board_room_response){var response=data.board_room_response+'\\n\\n---\\nMeeting ID: '+data.meeting_id+'\\nStatus: '+data.status;show(response);fillMinutes(data.board_room_response,'Meeting ID: '+data.meeting_id+' · Status: '+data.status)}else{show(data);fillMinutes(JSON.stringify(data),'Status: response-ready')}")
    return html
